const THROTTLE_MS = 5000;

function parsePayload(value) {
    if (!value) return {};
    if (typeof value === "string") {
        try { return JSON.parse(value); } catch (err) { return { raw: value }; }
    }
    if (Buffer.isBuffer(value)) {
        try { return JSON.parse(value.toString("utf8")); } catch (err) { return { raw: value.toString("utf8") }; }
    }
    return value && typeof value === "object" ? value : { raw: value };
}

function normalizeCpsId(value) {
    return String(value || "")
        .trim()
        .toLowerCase()
        .replace(/^cps-?0*/, "cps")
        .replace(/[^a-z0-9_-]/g, "");
}

const originalPayload = parsePayload(msg.payload);
const topicParts = String(msg.topic || "").split("/");
const topicCps = topicParts.length >= 3 && topicParts[0] === "acsm1" ? topicParts[1] : null;
const baseTopic = normalizeCpsId(originalPayload.baseTopic || originalPayload.cpsId || msg.baseTopic || msg.cpsId || topicCps || "cps7") || "cps7";
const now = Date.now();
const throttleState = flow.get("perCpsAiThrottle") || {};
const lastCallAt = Number(throttleState[baseTopic] || 0);

msg._aiOriginalPayload = originalPayload;
msg._aiEnrichmentContext = {
    cpsId: originalPayload.cpsId || baseTopic,
    baseTopic,
    sourceTopic: msg.topic,
    receivedAt: new Date(now).toISOString(),
    throttleMs: THROTTLE_MS
};

if (lastCallAt > 0 && now - lastCallAt < THROTTLE_MS) {
    const retryAfterMs = THROTTLE_MS - (now - lastCallAt);
    msg._aiEnrichmentContext.rateLimited = true;
    msg._aiEnrichmentContext.retryAfterMs = retryAfterMs;
    msg.aiInterpretation = {
        summary: "Generative AI interpretation skipped by the per-CPS throttle; publishing a freshness update with the latest structured analytics.",
        diagnosis: "No new AI diagnosis was generated because this CPS is still inside the throttle window.",
        prediction: "Prediction remains based on the latest available structured forecast from the CPS analytics payload.",
        recommendation: originalPayload.recommendation || originalPayload.reasoning?.recommendation || "Maintain the current operational monitoring strategy until the next AI enrichment window.",
        decisionJustification: "The existing analytics payload is preserved; the generative AI layer did not create or alter decisions.",
        riskInterpretation: originalPayload.riskLevel ? `Current structured risk level remains ${originalPayload.riskLevel}.` : "Risk interpretation is based on the latest structured analytics payload.",
        confidenceInterpretation: originalPayload.confidence != null ? `Current structured confidence remains ${originalPayload.confidence}.` : "Confidence interpretation is based on the latest structured analytics payload.",
        generatedAt: new Date(now).toISOString(),
        model: "fallback",
        fallback: true,
        reason: "rate_limit",
        retryAfterMs
    };
    node.status({ fill: "yellow", shape: "ring", text: `${baseTopic} throttled ${retryAfterMs}ms` });
    return [null, msg];
}

throttleState[baseTopic] = now;
flow.set("perCpsAiThrottle", throttleState);
node.status({ fill: "green", shape: "dot", text: `${baseTopic} AI allowed` });
return [msg, null];

const originalPayload = msg._aiOriginalPayload || (msg.payload && typeof msg.payload === "object" ? msg.payload : {});
const aiContext = msg._aiEnrichmentContext || {};
const endpoint = env.get("VERCEL_AI_DESCRIBE_URL") || "http://localhost:3000/api/ai/describe-level";

const knowledgePackage = originalPayload.knowledgePackage || originalPayload.analytics || originalPayload;

msg.method = "POST";
msg.url = endpoint;
msg.headers = {
    "Content-Type": "application/json"
};
msg.payload = {
    level: "level1",
    contextType: "operational",
    knowledgePackage,
    language: "en",
    outputType: "summary"
};

node.status({ fill: "blue", shape: "dot", text: `AI request ready for ${aiContext.baseTopic || "cps"}` });
node.warn({
    eventType: "AI_REQUEST_READY",
    cpsId: aiContext.cpsId || originalPayload.cpsId || aiContext.baseTopic,
    baseTopic: aiContext.baseTopic,
    endpoint: "/api/ai/describe-level"
});

return msg;

function toObject(value) {
    if (!value) return {};
    if (typeof value === "string") {
        try { return JSON.parse(value); } catch (err) { return { raw: value }; }
    }
    if (Buffer.isBuffer(value)) {
        try { return JSON.parse(value.toString("utf8")); } catch (err) { return { raw: value.toString("utf8") }; }
    }
    return value && typeof value === "object" ? value : { raw: value };
}

function normalizeCpsId(value) {
    return String(value || "")
        .trim()
        .toLowerCase()
        .replace(/^cps-?0*/, "cps")
        .replace(/[^a-z0-9_-]/g, "");
}

function fallbackFrom(originalPayload, reason) {
    const nowIso = new Date().toISOString();
    return {
        summary: "Generative AI interpretation fallback generated from the existing structured CPS analytics payload.",
        diagnosis: originalPayload.reasoning?.primaryIssue || originalPayload.reasoning?.diagnosis || "Structured analytics remain available; no new generative diagnosis was produced.",
        prediction: originalPayload.forecastOEE != null ? `Structured forecast OEE remains ${originalPayload.forecastOEE}.` : "Prediction remains based on the latest structured forecast fields, when available.",
        recommendation: originalPayload.recommendation || originalPayload.reasoning?.recommendation || "Maintain monitoring based on the current CPS analytics payload.",
        decisionJustification: "The AI interpretation layer did not change metrics, reasoning, decisions, MQTT topics, or feedback payloads.",
        riskInterpretation: originalPayload.riskLevel ? `Structured risk level: ${originalPayload.riskLevel}.` : "Risk level was not explicitly provided in the source payload.",
        confidenceInterpretation: originalPayload.confidence != null ? `Structured confidence: ${originalPayload.confidence}.` : "Confidence was not explicitly provided in the source payload.",
        generatedAt: nowIso,
        model: "fallback",
        fallback: true,
        reason
    };
}

const aiContext = msg._aiEnrichmentContext || {};
const originalPayload = msg._aiOriginalPayload || {};
const httpPayload = toObject(msg.payload);
const statusCode = Number(msg.statusCode || 0);
let aiInterpretation = msg.aiInterpretation || httpPayload;

if (msg.error || statusCode >= 400 || !aiInterpretation || typeof aiInterpretation !== "object" || Object.keys(aiInterpretation).length === 0) {
    aiInterpretation = fallbackFrom(originalPayload, msg.error ? "http_error" : `http_${statusCode || "empty_response"}`);
}

const baseTopic = normalizeCpsId(aiContext.baseTopic || originalPayload.baseTopic || originalPayload.cpsId || "cps7") || "cps7";
const nowIso = new Date().toISOString();

msg.topic = `acsm1/${baseTopic}/analytics/enriched`;
msg.payload = {
    ...originalPayload,
    aiInterpretation,
    generativeAIInterpretation: aiInterpretation,
    aiEnrichment: {
        generatedAt: aiInterpretation.generatedAt || nowIso,
        fallback: aiInterpretation.fallback === true,
        reason: aiInterpretation.reason || null,
        model: aiInterpretation.model || "gemini",
        source: aiContext.rateLimited ? "per_cps_throttle" : "vercel_describe_level"
    },
    enrichedAt: nowIso
};

node.status({ fill: aiInterpretation.fallback ? "yellow" : "green", shape: "dot", text: `${baseTopic} enriched${aiInterpretation.fallback ? " fallback" : ""}` });
return msg;
